import { useState, useEffect } from 'react';
import { useSearchParams, useNavigate } from 'react-router-dom';
import Button from '../components/Button';

export default function QuizPage() {
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const domain = searchParams.get('domain') || 'cybersecurity';
  
  const [questions, setQuestions] = useState([]);
  const [selected, setSelected] = useState({});
  const [submitted, setSubmitted] = useState(false);
  const [loading, setLoading] = useState(false);
  const [difficulty, setDifficulty] = useState(null);

  const fetchQuestions = async (level) => {
    setLoading(true);
    setDifficulty(level);
    try {
      const res = await fetch("http://localhost:5000/api/quiz/generate", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ domain, difficulty: level })
      });
      setQuestions(await res.json());
    } catch (err) { console.error(err); }
    finally { setLoading(false); }
  };

  const cleanStr = (s) => s ? s.replace(/^[a-z0-9][\s).:-]+/i, "").trim().toLowerCase() : "";

  const score = questions.reduce((acc, q, idx) => {
    return acc + (cleanStr(selected[idx]) === cleanStr(q.answer) ? 1 : 0);
  }, 0);

  const handleFinalContinue = () => {
    // Logic aligned with image: 3 months = 12 weeks = 12 phases
    const timeline = localStorage.getItem('timeline') || '3 months';
    const weeks = timeline.includes('month') ? parseInt(timeline) * 4 : parseInt(timeline);
    
    let pathLabel = score >= 8 ? "Advanced" : score <= 4 ? "Foundational" : "Standard";

    // Generating the 28-task phases shown in your image
    const generatedPlan = Array.from({ length: weeks }, (_, wIdx) => {
      return Array.from({ length: 28 }, (_, tIdx) => 
        `${pathLabel} ${domain} - Week ${wIdx + 1}, Task ${tIdx + 1}`
      );
    });

    localStorage.setItem('roadmapPlan', JSON.stringify(generatedPlan));
    localStorage.setItem('quizScore', score);
    localStorage.setItem('totalQuestions', questions.length);
    navigate(`/roadmap/${domain}`);
  };

  if (!difficulty && !loading) return (
    <div className="max-w-md mx-auto mt-20 p-10 bg-white rounded-[2rem] border text-center shadow-lg">
      <h2 className="text-2xl font-bold mb-6">Select Assessment Level</h2>
      <div className="flex flex-col gap-4">
        {['Easy', 'Medium', 'Hard'].map(lvl => (
          <Button key={lvl} onClick={() => fetchQuestions(lvl.toLowerCase())} className="capitalize">{lvl}</Button>
        ))}
      </div>
    </div>
  );

  if (loading) return <div className="p-20 text-center font-medium">✨ AI is generating 10 specific questions...</div>;

  return (
    <div className="max-w-4xl mx-auto p-4 space-y-6">
      <div className="bg-white rounded-[2rem] p-8 border shadow-sm">
        <h2 className="text-3xl font-bold capitalize mb-6">{domain.replace(/-/g, ' ')} ({difficulty})</h2>
        <div className="space-y-8">
          {questions.map((q, idx) => (
            <div key={idx} className="p-6 rounded-3xl bg-slate-50 border border-slate-100">
              <p className="font-semibold text-lg mb-4">{idx + 1}. {q.question}</p>
              <div className="grid gap-3 sm:grid-cols-2">
                {q.options.map(opt => {
                  const isSelected = selected[idx] === opt;
                  const isCorrect = cleanStr(opt) === cleanStr(q.answer);
                  
                  // Dynamic styling after submission
                  let buttonStyle = "border-slate-200 bg-white hover:border-blue-400";
                  if (isSelected) buttonStyle = "border-blue-600 bg-blue-600 text-white";
                  
                  if (submitted) {
                    if (isCorrect) buttonStyle = "border-green-500 bg-green-50 text-green-900 ring-4 ring-green-100";
                    else if (isSelected && !isCorrect) buttonStyle = "border-red-500 bg-red-50 text-red-900";
                  }

                  return (
                    <button
                      key={opt}
                      disabled={submitted}
                      onClick={() => setSelected(prev => ({ ...prev, [idx]: opt }))}
                      className={`p-4 text-left border rounded-2xl transition-all font-medium ${buttonStyle}`}
                    >
                      {opt}
                    </button>
                  );
                })}
              </div>
            </div>
          ))}
        </div>
        <div className="mt-8 border-t pt-8">
          {!submitted ? (
            <Button 
              onClick={() => setSubmitted(true)} 
              disabled={Object.keys(selected).length < questions.length}
              className="w-full sm:w-auto px-10"
            >
              Submit Assessment
            </Button>
          ) : (
            <div className="flex flex-col sm:flex-row justify-between items-center gap-4">
              <div className="text-2xl font-bold text-teal-600">
                Performance: {score} / 10 Correct
              </div>
              <Button onClick={handleFinalContinue} className="w-full sm:w-auto">
                Generate My Roadmap →
              </Button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
